# 1来訪あたり広告費（LPV単価）上昇の原因を、考えられる切り口すべてで分解する（2026-10-31 22時台）
# データはすべて Supermetrics FA（act_1124340806289175・fresh・Asia/Tokyo）の当日クエリ結果を転記したもの。
# A = 10/24-28、B = 10/29-31（10/31は22時台途中まで）。終日の切り口（年齢・端末・時間帯・ランキング）は0〜20時台に揃えられないので終日。
import math

def r(c, i, o, l=None):
    d = dict(CPM=c / i * 1000 if i else 0, CTR=o / i * 100 if i else 0, CPC=c / o if o else 0)
    if l: d['CPL'] = c / l
    return d

def mix_within(A, B, unit):
    """B の構成（消化の割合）のまま A の単価だったら → 構成効果。残りが中身の変化"""
    ca = sum(v[0] for v in A.values()); ua = sum(v[unit] for v in A.values())
    cb = sum(v[0] for v in B.values()); ub = sum(v[unit] for v in B.values())
    keys = [k for k in B if k in A and A[k][unit]]
    u_mix = sum(B[k][0] / (A[k][0] / A[k][unit]) for k in keys) + sum(B[k][unit] for k in B if k not in keys)
    return ca / ua, cb / ub, cb / u_mix

